actions.script:
const WORDS = [
    ['negative', /(cancel|reject|void|lost|fail|error|declin|denied|abort|refus)/i],
    ['positive', /(complete|paid|shipped|deliver|won|resolved|closed|finish|done|confirm|consumed|accepted|success)/i],
    ['warning', /(hold|pending|overdue|backorder|wait|paus|suspend|expir)/i],
    ['grey-7', /(draft|propos|creat|request|planning|notstart|not started|unassign|inactive|produced|^new|\snew)/i],
    ['info', /(sent|received|viewed|scheduled|invoiced|submitted|ready)/i],
    ['primary', /(approv|progress|open|active|picking|assigned|placed|process|running|sending|consuming|started)/i]
]
const byWords = (text) => {
    if (!text) return null
    for (const [color, pattern] of WORDS) if (pattern.test(String(text))) return color
    return null
}
colors = {}
for (const raw of Array.from(statusIdList || [])) {
    if (raw == null || raw === '') continue
    const id = String(raw)
    if (colors[id]) continue
    const item = ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).disableAuthz().one()
    colors[id] = (item && item.statusColor ? String(item.statusColor) : null) || byWords(id) || byWords(item ? item.description : null) || 'grey-7'
}

const text = (value) => (value == null ? '' : String(value).trim())
const currentId = text(statusId) || null
const flowId = text(statusFlowId) || 'Default'
const itemOf = (id) => id ? ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).disableAuthz().one() : null
const currentItem = itemOf(currentId)
statusTypeId = text(statusTypeId) || (currentItem ? text(currentItem.statusTypeId) : '') || null
const typeItems = statusTypeId ? Array.from(ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId', statusTypeId)
        .orderBy('sequenceNum').orderBy('statusId').useCache(true).disableAuthz().list()) : []
const flowRows = currentId ? Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', flowId)
        .condition('statusId', currentId).orderBy('transitionSequence').orderBy('toStatusId').useCache(true).disableAuthz().list()) : []
const allIds = typeItems.map((item) => String(item.statusId)).concat(currentId ? [currentId] : [])
        .concat(flowRows.map((row) => String(row.toStatusId))).concat(Array.from(stageStatusIds || []).map(String))
const colors = ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors').parameter('statusIdList', allIds).call()?.colors || {}
const colorOf = (id) => colors[id] || 'grey-7'
const labelOf = (id) => { const item = itemOf(id); return item ? (text(item.description) || id) : (id || '') }
const sequenceOf = (id) => { const item = itemOf(id); return item && item.sequenceNum != null ? Number(item.sequenceNum) : 0 }
const offPath = (id) => ['warning', 'negative'].includes(colorOf(id))

// the stages: given, else the type's statuses in order without the ones that wait or end badly
let stageIds = Array.from(stageStatusIds || []).map(text).filter((id) => id)
if (!stageIds.length) {
    let inFlow = null
    if (flowId !== 'Default') {
        const flowItems = Array.from(ec.entity.find('moqui.basic.StatusFlowItem').condition('statusFlowId', flowId).useCache(true).disableAuthz().list())
        if (flowItems.length) inFlow = new Set(flowItems.map((row) => String(row.statusId)))
    }
    stageIds = typeItems.map((item) => String(item.statusId)).filter((id) => !offPath(id) && (!inFlow || inFlow.has(id)))
}

current = currentId ? {statusId: currentId, label: labelOf(currentId), color: colorOf(currentId)} : null
const currentIndex = currentId ? stageIds.indexOf(currentId) : -1
// off the stages: after the last stage whose sequence is not past the current one's, the stages before it done; one that
// ended badly is last, with nothing done
let reached = currentIndex
let insertAfter = -2
if (currentIndex < 0 && currentId) {
    const sequence = sequenceOf(currentId)
    reached = -1
    stageIds.forEach((id, index) => { if (sequenceOf(id) <= sequence) reached = index })
    insertAfter = reached
    if (current.color === 'negative') { reached = -1; insertAfter = stageIds.length - 1 }
}
const currentStage = current ? {statusId: currentId, label: current.label, color: current.color, state: 'current'} : null
stages = []
if (insertAfter === -1) stages.push(currentStage)
stageIds.forEach((id, index) => {
    const state = id === currentId ? 'current' : (index < reached || (currentIndex < 0 && index <= reached) ? 'done' : 'todo')
    stages.push({statusId: id, label: labelOf(id), color: colorOf(id), state: state})
    if (index === insertAfter) stages.push(currentStage)
})

// the transitions the user may take
const allowed = allowedToStatusIds == null ? null : Array.from(allowedToStatusIds).map(text)
const seen = new Set()
transitions = []
for (const row of flowRows) {
    const to = String(row.toStatusId)
    if (seen.has(to) || (allowed != null && !allowed.includes(to))) continue
    if (row.userPermissionId && !ec.user.hasPermission(String(row.userPermissionId))) continue
    seen.add(to)
    transitions.push({toStatusId: to, label: row.transitionName ? ec.l10n.localize(String(row.transitionName)) : labelOf(to), color: colorOf(to),
        isNext: false, isDanger: colorOf(to) === 'negative', stageIndex: stageIds.indexOf(to)})
}
let pick = null
for (const transition of transitions) {
    if (transition.stageIndex < 0 || transition.isDanger) continue
    if (currentIndex >= 0 && transition.stageIndex <= currentIndex) continue
    if (pick == null || transition.stageIndex < pick.stageIndex) pick = transition
}
if (pick) pick.isNext = true
next = pick
const rank = (transition) => (transition.isNext ? 0 : transition.isDanger ? 2 : 1)
transitions.sort((left, right) => rank(left) - rank(right) || (left.stageIndex < 0 ? 99 : left.stageIndex) - (right.stageIndex < 0 ? 99 : right.stageIndex))

const text = (value) => (value == null ? '' : String(value).trim())
const given = Array.from(values || []).map(text).filter((value) => value)
const find = (entity, field, value) => ec.entity.find(entity).condition(field, value).useCache(true).disableAuthz().one()
const items = []
const seen = new Set()
const add = (value, label, isStatus) => {
    if (!value || seen.has(value)) return
    seen.add(value)
    items.push({value: value, label: label || value, isStatus: isStatus})
}
if (status || text(statusTypeId)) {
    const types = []
    if (text(statusTypeId)) types.push(text(statusTypeId))
    else for (const value of given) {
        const item = find('moqui.basic.StatusItem', 'statusId', value)
        if (item && item.statusTypeId && !types.includes(String(item.statusTypeId))) types.push(String(item.statusTypeId))
    }
    for (const type of types) {
        const typeItems = Array.from(ec.entity.find('moqui.basic.StatusItem').condition('statusTypeId', type)
                .orderBy('sequenceNum').orderBy('statusId').useCache(true).disableAuthz().list())
        for (const item of typeItems) add(String(item.statusId), text(item.description), true)
    }
}
for (const value of given) {
    if (seen.has(value)) continue
    const item = find('moqui.basic.StatusItem', 'statusId', value)
    if (item) { add(value, text(item.description), true); continue }
    const enumeration = find('moqui.basic.Enumeration', 'enumId', value)
    add(value, enumeration ? text(enumeration.description) : value, false)
}
const statusIds = items.filter((item) => item.isStatus).map((item) => item.value)
const colors = statusIds.length ? (ec.service.sync().name('org.moqui.ui.StatusServices.get#StatusColors')
        .parameter('statusIdList', statusIds).call()?.colors || {}) : {}
columns = items.map((item) => ({value: item.value, label: item.label, color: item.isStatus ? (colors[item.value] || 'grey-7') : null}))
flow = []
if (statusIds.length) {
    const rows = Array.from(ec.entity.find('moqui.basic.StatusFlowTransition').condition('statusFlowId', text(statusFlowId) || 'Default')
            .condition('statusId', 'in', statusIds).orderBy('statusId').orderBy('transitionSequence').orderBy('toStatusId').useCache(true).disableAuthz().list())
    for (const row of rows) {
        if (row.userPermissionId && !ec.user.hasPermission(String(row.userPermissionId))) continue
        flow.push({statusId: String(row.statusId), toStatusId: String(row.toStatusId)})
    }
}
